package io.clipbridge.android;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.io.*;
import java.util.*;
import okhttp3.*;
final class MediaWire {
    private final JSONObject config;private final String origin,authorization;private final boolean dav;private final Set<String> created=new HashSet<>();private boolean capable;
    private static final OkHttpClient HTTP=new OkHttpClient.Builder().followRedirects(false).followSslRedirects(false).connectTimeout(10,java.util.concurrent.TimeUnit.SECONDS).readTimeout(35,java.util.concurrent.TimeUnit.SECONDS).callTimeout(45,java.util.concurrent.TimeUnit.SECONDS).build();
    MediaWire(JSONObject c)throws Exception{config=c;Protocol.config(c);origin=c.getString("server").replaceAll("/+$","")+"/";dav="webdav".equals(c.optString("transport"));authorization=dav?"Basic "+Protocol.encode((c.getString("username")+":"+c.getString("password")).getBytes(StandardCharsets.UTF_8)):"Bearer "+c.getString("token");}
    private String path(String device,String key)throws Exception{return dav?"clipbridge/"+config.getString("pair")+"/"+(key.equals("index")?device+".transfers.json":"attachments/"+device+"/"+key+".bin"):"v1/objects/"+device+"/"+key;}
    private void ensure(boolean blob)throws Exception{if(!dav)return;String base="clipbridge/"+config.getString("pair")+"/";for(String path:new String[]{"clipbridge/",base,blob?base+"attachments/":"",blob?base+"attachments/"+config.getString("device")+"/":""})if(!path.isEmpty()&&!created.contains(path)){exchange("MKCOL",path,null);created.add(path);}}
    private void capability()throws Exception{if(dav||capable)return;byte[] data=exchange("GET","v1/setup/info",null);if(data==null||new JSONObject(new String(data,StandardCharsets.UTF_8)).optInt("attachments")!=1)throw new IOException("Update relay for attachments");capable=true;}
    JSONObject index()throws Exception{capability();byte[] data=exchange("GET",path(config.getString("peer"),"index"),null);return data==null?null:MediaProtocol.openIndex(config,new String(data,StandardCharsets.UTF_8));}
    void index(JSONObject index)throws Exception{capability();ensure(false);exchange("PUT",path(config.getString("device"),"index"),MediaProtocol.sealIndex(config,index).getBytes(StandardCharsets.UTF_8));}
    void put(String id,int part,byte[] plain)throws Exception{capability();ensure(true);exchange("PUT",path(config.getString("device"),id+"-"+part),MediaProtocol.encrypt(config,id,part,plain));}
    byte[] get(String id,int part)throws Exception{capability();byte[] bytes=exchange("GET",path(config.getString("peer"),id+"-"+part),null);if(bytes==null)throw new IOException("Not ready");return MediaProtocol.decrypt(config,id,part,bytes);}
    void delete(String id,int part)throws Exception{if(dav&&part>0)return;exchange("DELETE",dav?bundlePath(config.getString("device"),id):path(config.getString("device"),id+"-"+part),null);}
    private byte[] exchange(String method,String path,byte[] body)throws Exception{RequestBody data=body==null?null:RequestBody.create(body,MediaType.parse("application/octet-stream"));Request request=new Request.Builder().url(origin+path).method(method,data).header("Authorization",authorization).header("Cache-Control","no-store, no-cache").build();try(Response response=HTTP.newCall(request).execute()){if((method.equals("GET")||method.equals("DELETE"))&&response.code()==404)return null;if(method.equals("MKCOL")&&response.code()==405)return null;if(method.equals("DELETE")&&(response.code()==403||response.code()==405||response.code()==501))return null;if(!response.isSuccessful())throw new IOException("Transfer HTTP "+response.code());if(!method.equals("GET"))return new byte[0];if(response.body()==null)throw new IOException();try(InputStream input=response.body().byteStream();ByteArrayOutputStream output=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=input.read(buffer))!=-1){if(output.size()+n>600000)throw new IOException("Oversized transfer response");output.write(buffer,0,n);}return output.toByteArray();}}}
    private static final OkHttpClient BULK=HTTP.newBuilder().callTimeout(10,java.util.concurrent.TimeUnit.MINUTES).writeTimeout(2,java.util.concurrent.TimeUnit.MINUTES).readTimeout(2,java.util.concurrent.TimeUnit.MINUTES).build();
    private String bundlePath(String device,String id)throws Exception{return path(device,id+"-0").replace(id+"-0.bin",id+".cbx");}
    void putBundle(File source,JSONObject offer)throws Exception{
        MediaProtocol.validate(offer);ensure(true);final long size=offer.getLong("size");final int chunks=offer.getInt("chunks");final String id=offer.getString("id");
        RequestBody body=new RequestBody(){public MediaType contentType(){return MediaType.parse("application/octet-stream");}public long contentLength(){return size+28L*chunks;}public void writeTo(okio.BufferedSink sink)throws IOException{try(RandomAccessFile input=new RandomAccessFile(source,"r")){if(input.length()!=size)throw new IOException("Source changed");for(int part=0;part<chunks;part++){byte[] plain=new byte[(int)Math.min(MediaProtocol.CHUNK,size-input.getFilePointer())];input.readFully(plain);try{sink.write(MediaProtocol.encrypt(config,id,part,plain));}catch(Exception e){throw new IOException(e);}}}}};
        Request request=new Request.Builder().url(origin+bundlePath(config.getString("device"),id)).put(body).header("Authorization",authorization).build();try(Response response=BULK.newCall(request).execute()){if(!response.isSuccessful())throw new IOException("WebDAV upload HTTP "+response.code());}
    }
    void getBundle(JSONObject offer,File target)throws Exception{
        MediaProtocol.validate(offer);String id=offer.getString("id");long size=offer.getLong("size");int chunks=offer.getInt("chunks");Request request=new Request.Builder().url(origin+bundlePath(config.getString("peer"),id)).header("Authorization",authorization).header("Cache-Control","no-cache, no-store").build();
        try(Response response=BULK.newCall(request).execute()){if(!response.isSuccessful()||response.body()==null)throw new IOException("WebDAV download HTTP "+response.code());long length=response.body().contentLength();if(length>=0&&length!=size+28L*chunks)throw new IOException("Encrypted size mismatch");try(DataInputStream input=new DataInputStream(response.body().byteStream());OutputStream output=new FileOutputStream(target)){for(int part=0;part<chunks;part++){int plain=(int)Math.min(MediaProtocol.CHUNK,size-(long)part*MediaProtocol.CHUNK);byte[] cipher=new byte[plain+28];input.readFully(cipher);output.write(MediaProtocol.decrypt(config,id,part,cipher));}if(input.read()!=-1)throw new IOException("Trailing encrypted data");}}
    }
}
